/**
 * QR decode and payload tests against real photo fixtures.
 * Run with: node tests/qr.test.mjs
 *
 * The fixtures are actual QR-bearing photos (generated by tests/make-fixtures.mjs
 * and tests/make-exif-fixture.py). Nothing here mocks the decoder: PNG/JPEG
 * pixels are decoded with pngjs/jpeg-js and fed to the vendored jsQR decoder
 * through the same scan/parse modules the browser page uses.
 */

import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import path from "node:path";
import vm from "node:vm";
import { PNG } from "pngjs";
import jpeg from "jpeg-js";
import { parseQrPayload, resolvePhotoQr, isValidTrapId } from "../js/lib/qr.js";
import { readExifOrientation, applyExifOrientation } from "../js/lib/exif.js";
import { scanQrCodes } from "../js/lib/qr-scan.js";

const FIXTURES = path.resolve(import.meta.dirname, "fixtures");
const OWN_ORIGIN = "https://capture.example.com";
const TRAP = "VD-TEST-001";

// The vendored build is the exact pinned jsqr@1.4.0 UMD artifact. In the
// browser it is a classic script that sets window.jsQR. For the offline
// tests the unmodified bytes run in an isolated CommonJS VM context.
const jsQrSource = await readFile(path.resolve(import.meta.dirname, "../vendor/jsQR.js"), "utf8");
const sandbox = { module: { exports: {} }, console };
sandbox.exports = sandbox.module.exports;
vm.runInNewContext(jsQrSource, sandbox, { filename: "vendor/jsQR.js" });
const jsQR = sandbox.module.exports;
assert.equal(typeof jsQR, "function", "vendored jsQR must load as CommonJS");

let passed = 0;
function test(name, fn) {
  return Promise.resolve()
    .then(fn)
    .then(() => {
      passed += 1;
      console.log(`ok - ${name}`);
    })
    .catch((error) => {
      console.error(`FAIL - ${name}`);
      throw error;
    });
}

async function decodePng(name) {
  return PNG.sync.read(await readFile(path.join(FIXTURES, name)));
}

function pngToRgba(png) {
  return { data: new Uint8ClampedArray(png.data), width: png.width, height: png.height };
}

function decodeFirst(image) {
  const result = jsQR(image.data, image.width, image.height, { inversionAttempts: "dontInvert" });
  return result ? result.data : null;
}

/** The test uses the exact same scan strategy as the browser page. */
function scanAll(image) {
  return scanQrCodes(image.data, image.width, image.height, (pixels, w, h) => {
    const result = jsQR(pixels, w, h, { inversionAttempts: "dontInvert" });
    return result ? { data: result.data, location: result.location } : null;
  });
}

await test("the token fixture is a real photo with a readable QR", async () => {
  const image = pngToRgba(await decodePng("photo-qr-token.png"));
  assert.equal(decodeFirst(image), `VD1:TRAP:${TRAP}`);
});

await test("token payload parses to the trap id", () => {
  const parsed = parseQrPayload(`VD1:TRAP:${TRAP}`, { ownOrigin: OWN_ORIGIN });
  assert.equal(parsed.status, "trap");
  assert.equal(parsed.trapId, TRAP);
});

await test("token payload rejects malformed ids", () => {
  for (const bad of ["VD1:TRAP:", "VD1:TRAP:X", "VD1:TRAP:HAS SPACE", "VD1:TRAP:lower_case", `VD1:TRAP:${"A".repeat(41)}`]) {
    const parsed = parseQrPayload(bad, { ownOrigin: OWN_ORIGIN });
    assert.equal(parsed.status, "unknown", bad);
  }
  assert.equal(isValidTrapId("VD-001"), true);
  assert.equal(isValidTrapId("V"), false);
  assert.equal(isValidTrapId("VD_001"), false);
});

await test("legacy details label fixture decodes and yields the ID line", async () => {
  const image = pngToRgba(await decodePng("photo-qr-legacy.png"));
  const text = decodeFirst(image);
  assert.ok(text && text.startsWith("VECTORDOCK CONTAINER"), text);
  const parsed = parseQrPayload(text, { ownOrigin: OWN_ORIGIN });
  assert.equal(parsed.status, "trap");
  assert.equal(parsed.trapId, TRAP);
});

await test("legacy label ignores location/date as authority and rejects conflicts", () => {
  const ok = parseQrPayload("VECTORDOCK CONTAINER\nID: VD-9\nSite: somewhere\nLocation: private\nDeployed: 2020-01-01", { ownOrigin: OWN_ORIGIN });
  assert.equal(ok.trapId, "VD-9");
  const noId = parseQrPayload("VECTORDOCK CONTAINER\nSite: x", { ownOrigin: OWN_ORIGIN });
  assert.equal(noId.status, "unknown");
  const twoIds = parseQrPayload("VECTORDOCK CONTAINER\nID: VD-1\nID: VD-2", { ownOrigin: OWN_ORIGIN });
  assert.equal(twoIds.status, "unknown");
  assert.match(twoIds.reason, /conflicting/);
  const malformed = parseQrPayload("VECTORDOCK CONTAINER\nID: no no", { ownOrigin: OWN_ORIGIN });
  assert.equal(malformed.status, "unknown");
});

await test("capture URL fixture decodes and is accepted only for the configured origin", async () => {
  const image = pngToRgba(await decodePng("photo-qr-capture-url.png"));
  const text = decodeFirst(image);
  assert.equal(text, `${OWN_ORIGIN}/capture?trap=${TRAP}`);
  assert.equal(parseQrPayload(text, { ownOrigin: OWN_ORIGIN }).trapId, TRAP);
  const foreign = parseQrPayload(text, { ownOrigin: "https://other.example.com" });
  assert.equal(foreign.status, "unknown");
  assert.match(foreign.reason, /never opens/);
});

await test("capture URL rejects duplicate or conflicting trap parameters, even identical values", () => {
  const dup = parseQrPayload(`${OWN_ORIGIN}/capture?trap=${TRAP}&trap=VD-9`, { ownOrigin: OWN_ORIGIN });
  assert.equal(dup.status, "unknown");
  assert.match(dup.reason, /duplicated or conflicting/);
  const identical = parseQrPayload(`${OWN_ORIGIN}/capture?trap=${TRAP}&trap=${TRAP}`, { ownOrigin: OWN_ORIGIN });
  assert.equal(identical.status, "unknown");
  assert.match(identical.reason, /duplicated or conflicting/);
  const missing = parseQrPayload(`${OWN_ORIGIN}/capture`, { ownOrigin: OWN_ORIGIN });
  assert.equal(missing.status, "unknown");
  const wrongPath = parseQrPayload(`${OWN_ORIGIN}/other?trap=${TRAP}`, { ownOrigin: OWN_ORIGIN });
  assert.equal(wrongPath.status, "unknown");
});

await test("maps QR fixture carries no container id", async () => {
  const image = pngToRgba(await decodePng("photo-qr-maps.png"));
  const text = decodeFirst(image);
  assert.ok(text && text.includes("maps"), text);
  const resolved = resolvePhotoQr([text], { ownOrigin: OWN_ORIGIN });
  assert.equal(resolved.status, "unknown");
  assert.match(resolved.reasons[0], /no container ID/);
});

await test("conflict fixture resolves to two distinct ids, never a silent choice", async () => {
  const image = pngToRgba(await decodePng("photo-qr-conflict.png"));
  // A full-frame jsQR pass legitimately fails with two codes in one frame;
  // the shared tile scan (the browser's actual strategy) must find both.
  const texts = scanAll(image);
  assert.equal(texts.length, 2, JSON.stringify(texts));
  const resolved = resolvePhotoQr(texts, { ownOrigin: OWN_ORIGIN });
  assert.equal(resolved.status, "conflict");
  assert.deepEqual(resolved.ids, [TRAP, "VD-OTHER-9"].sort());
});

await test("duplicate (identical) QRs are not a conflict", async () => {
  const image = pngToRgba(await decodePng("photo-qr-duplicate.png"));
  const resolved = resolvePhotoQr(scanAll(image), { ownOrigin: OWN_ORIGIN });
  assert.equal(resolved.status, "trap");
  assert.equal(resolved.trapId, TRAP);
});

await test("no-QR fixture reports no_qr, not a guessed trap", async () => {
  const image = pngToRgba(await decodePng("photo-no-qr.png"));
  assert.equal(decodeFirst(image), null);
  assert.equal(resolvePhotoQr([], { ownOrigin: OWN_ORIGIN }).status, "no_qr");
});

await test("wrong-trap fixture decodes a different, valid id", async () => {
  const image = pngToRgba(await decodePng("photo-qr-wrong-trap.png"));
  const text = decodeFirst(image);
  assert.equal(text, "VD1:TRAP:VD-OTHER-9");
  assert.equal(resolvePhotoQr([text], { ownOrigin: OWN_ORIGIN }).trapId, "VD-OTHER-9");
});

await test("EXIF fixture stores orientation 6 and reads back as 6", async () => {
  const bytes = new Uint8Array(await readFile(path.join(FIXTURES, "photo-qr-token-exif6.jpg")));
  assert.equal(readExifOrientation(bytes), 6);
});

await test("the rotated EXIF JPEG decodes only after normalization", async () => {
  const bytes = new Uint8Array(await readFile(path.join(FIXTURES, "photo-qr-token-exif6.jpg")));
  const raw = jpeg.decode(bytes, { useTArray: true, maxMemoryUsageInMB: 64 });
  const rgba = toRgba(raw);
  // jsQR is robust enough to read the sideways code in a single pass; the
  // required property is that EXIF normalization produces the same intended
  // payload with the displayed (transposed) dimensions.
  const unnormalized = decodeFirst(rgba);
  if (unnormalized !== null) {
    assert.equal(unnormalized, `VD1:TRAP:${TRAP}`);
  }
  const normalized = applyExifOrientation(rgba.data, rgba.width, rgba.height, 6);
  assert.equal(normalized.width, 420);
  assert.equal(normalized.height, 320);
  assert.equal(decodeFirst(normalized), `VD1:TRAP:${TRAP}`);
});

await test("the page exposes separate Take picture and Upload photo controls on one decode path", async () => {
  const html = await readFile(path.resolve(import.meta.dirname, "../index.html"), "utf8");
  const app = await readFile(path.resolve(import.meta.dirname, "../js/app.js"), "utf8");
  assert.match(html, /id="cameraInput"[^>]*capture="environment"/);
  assert.match(html, /id="photoInput"/);
  assert.doesNotMatch(html, /id="photoInput"[^>]*capture=/);
  assert.match(app, /decodePhotoQrPayloads/);
  assert.doesNotMatch(app, /BarcodeDetector/);
});

function toRgba(raw) {
  const data = new Uint8ClampedArray(raw.width * raw.height * 4);
  for (let i = 0, j = 0; i < raw.width * raw.height; i += 1, j += 4) {
    data[j] = raw.data[i * 4];
    data[j + 1] = raw.data[i * 4 + 1];
    data[j + 2] = raw.data[i * 4 + 2];
    data[j + 3] = 255;
  }
  return { data, width: raw.width, height: raw.height };
}

console.log(`\nqr.test: ${passed} checks passed`);
